// PRIMARY: crates/stages/stages/src/stages/sender_recovery.rs:recover_sender (lines 308-323)
#[inline]
fn recover_sender<T: SignedTransaction>(
    (tx_id, tx): (TxNumber, T),
    rlp_buf: &mut Vec<u8>,
) -> Result<(u64, Address), Box<SenderRecoveryStageError>> {
    rlp_buf.clear();
    // We call [Signature::encode_and_recover_unchecked] because transactions run in the pipeline
    // are known to be valid - this means that we do not need to check whether or not the `s`
    // value is greater than `secp256k1n / 2` if past EIP-2. There are transactions
    // pre-homestead which have large `s` values, so using [Signature::recover_signer] here
    // would not be backwards-compatible.
    let sender = tx.recover_unchecked_with_buf(rlp_buf).map_err(|_| {
        SenderRecoveryStageError::FailedRecovery(FailedSenderRecoveryError { tx: tx_id })
    })?;
    Ok((tx_id, sender))
}

// PRIMARY: crates/stages/stages/src/stages/sender_recovery.rs:recover_sender (lines 308-323)
// ECDSA r/s range validation is performed inside tx.recover_unchecked_with_buf() which
// delegates to the alloy-primitives / k256 secp256k1 library.
// The comment notes that for pipeline (known-valid) txs, unchecked recovery is used.
// For incoming (untrusted) transactions, recover_signer() enforces EIP-2 low-s.
// r range validation (0 < r < SECP256K1N) is enforced by the underlying secp256k1 library.
let sender = tx.recover_unchecked_with_buf(rlp_buf).map_err(|_| {
    SenderRecoveryStageError::FailedRecovery(FailedSenderRecoveryError { tx: tx_id })
})?;

// PRIMARY: crates/stages/stages/src/stages/sender_recovery.rs:recover_sender (lines 307-323)
// EIP-2 low-s enforcement: pipeline uses recover_unchecked (for pre-homestead compat).
// For new incoming transactions, Signature::recover_signer() enforces EIP-2 low-s check.
// The code comment explicitly states: "s value is greater than secp256k1n / 2 if past EIP-2"
// - this check is in recover_signer (not recover_unchecked_with_buf).
// recover_unchecked skips EIP-2 check intentionally for backward compatibility.
#[inline]
fn recover_sender<T: SignedTransaction>(
    (tx_id, tx): (TxNumber, T),
    rlp_buf: &mut Vec<u8>,
) -> Result<(u64, Address), Box<SenderRecoveryStageError>> {
    // [Signature::recover_signer] would check s <= secp256k1n/2 (EIP-2)
    // but we use recover_unchecked for pre-homestead backward compatibility
    let sender = tx.recover_unchecked_with_buf(rlp_buf)...;
}

